<?php declare(strict_types=1);namespace StudPulse\Integrations;use StudPulse\Database\DB;use StudPulse\Http\ApiError;use StudPulse\Security\Crypto;final class MpeiMailDrafts{private const CHUNK=524288;public static function listing(array$scope,int$page):array{$offset=$page*25;$rows=DB::all("SELECT * FROM mpei_mail_drafts WHERE user_id=? AND mailbox_key=?
            ORDER BY updated_at DESC,id DESC LIMIT 26 OFFSET $offset",$scope);$summary=array_fill_keys(['id','to','subject','date','revision','sending'],true);return['items'=>array_map(static fn(array$row):array=>array_intersect_key(self::decode($row),$summary),array_slice($rows,0,25)),'hasMore'=>count($rows)>25,];}public static function get(array$scope,string$id,bool$lock=false):array{$row=DB::one('SELECT * FROM mpei_mail_drafts WHERE user_id=? AND mailbox_key=? AND id=?'.($lock?' FOR UPDATE':''),[...$scope,$id]);if(!$row)throw new ApiError(404,'MPEI_MAIL_DRAFT','Черновик не найден.');return self::decode($row);}public static function save(array$scope,string$id,int$revision,array$fields,array$files,array$removed):array{return DB::transaction(static function()use($scope,$id,$revision,$fields,$files,$removed):array{$existing=DB::one('SELECT * FROM mpei_mail_drafts WHERE user_id=? AND mailbox_key=? AND id=? FOR UPDATE',[...$scope,$id]);if($existing){self::assertEditable($existing,$revision);$saved=self::decode($existing)['files'];}elseif($revision===0){DB::run('INSERT INTO mpei_mail_drafts(id,user_id,mailbox_key,ciphertext,revision) VALUES(?,?,?,?,0)',[$id,...$scope,self::seal($scope,$id,$fields+['files'=>[]])]);$saved=[];}else{throw new ApiError(404,'MPEI_MAIL_DRAFT','Черновик не найден.');}$saved=array_values(array_filter($saved,static fn(array$file):bool=>!in_array($file['id'],$removed,true)));if(count($saved)+count($files)>10){throw new ApiError(422,'VALIDATION','К одному письму можно прикрепить до 10 файлов.');}foreach($removed as$file)DB::run('DELETE FROM mpei_mail_draft_parts WHERE draft_id=? AND file_id=?',[$id,$file]);foreach($files as[$name,$path]){$file=DB::id();$size=self::writeFile($id,$file,$path);$saved[]=['id'=>$file,'name'=>$name,'size'=>$size];}$ciphertext=self::seal($scope,$id,$fields+['files'=>$saved]);DB::run('UPDATE mpei_mail_drafts SET revision=revision+1,ciphertext=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?',[$ciphertext,$id]);return['id'=>$id,'revision'=>$revision+1,'files'=>$saved];});}public static function remove(array$scope,string$id,int$revision):void{DB::transaction(static function()use($scope,$id,$revision):void{$row=self::get($scope,$id,true);if($row['revision']!==$revision)self::conflict();DB::run('DELETE FROM mpei_mail_draft_parts WHERE draft_id=?',[$id]);DB::run('DELETE FROM mpei_mail_drafts WHERE id=? AND user_id=? AND mailbox_key=?',[$id,...$scope]);});}public static function reserve(array$scope,string$id,int$revision):array{return DB::transaction(static function()use($scope,$id,$revision):array{$draft=self::get($scope,$id,true);if($draft['sending'])throw new ApiError(409,'MPEI_MAIL_DELIVERY_UNKNOWN','Проверьте «Отправленные». Черновик сохранён, пока доставка неизвестна.');if($draft['revision']!==$revision)self::conflict();DB::run('UPDATE mpei_mail_drafts SET sending=1 WHERE id=?',[$id]);return$draft;});}public static function finish(array$scope,string$id,bool$sent):void{DB::run(($sent?'DELETE FROM mpei_mail_drafts':'UPDATE mpei_mail_drafts SET sending=0').' WHERE id=? AND user_id=? AND mailbox_key=?',[$id,...$scope]);}public static function temporaryAttachments(array$draft):array{$result=[];try{foreach($draft['files']as['id'=>$file,'name'=>$name,'size'=>$size]){$handle=tmpfile();if(!$handle)throw self::storageError();$result[]=[$name,stream_get_meta_data($handle)['uri'],$handle];$parts=(int)ceil($size/self::CHUNK);for($part=0;$part<$parts;++$part){$row=DB::one('SELECT ciphertext FROM mpei_mail_draft_parts WHERE draft_id=? AND file_id=? AND part=?',[$draft['id'],$file,$part]);if(!$row)throw self::storageError();$plain=Crypto::decrypt($row['ciphertext']);$binding=self::binding($draft['id'],$file,$part);if(!str_starts_with($plain,$binding))throw self::storageError();$bytes=substr($plain,strlen($binding));if(strlen($bytes)!==min(self::CHUNK,$size-$part*self::CHUNK)||fwrite($handle,$bytes)!==strlen($bytes)){throw self::storageError();}}fflush($handle);}return$result;}catch(\Throwable$error){foreach($result as[,,$handle])fclose($handle);throw$error;}}private static function writeFile(string$draft,string$file,string$path):int{$handle=fopen($path,'rb');if(!$handle)throw self::storageError();$part=0;$size=0;try{while(!feof($handle)){$bytes=fread($handle,self::CHUNK);if($bytes===false)throw self::storageError();if($bytes==='')break;$ciphertext=Crypto::encrypt(self::binding($draft,$file,$part).$bytes);DB::run('INSERT INTO mpei_mail_draft_parts(draft_id,file_id,part,ciphertext) VALUES(?,?,?,?)',[$draft,$file,$part++,$ciphertext]);$size+=strlen($bytes);}}finally{fclose($handle);}return$size;}private static function binding(string$draft,string$file,int$part):string{return"$draft:$file:$part:";}private static function decode(array$row):array{$data=json_decode(Crypto::decrypt($row['ciphertext']),true,16,JSON_THROW_ON_ERROR);if($data['owner']!==[$row['user_id'],$row['mailbox_key'],$row['id']])throw self::storageError();return$data['draft']+['id'=>$row['id'],'revision'=>(int)$row['revision'],'sending'=>(bool)$row['sending'],'date'=>gmdate('c',strtotime($row['updated_at'].' UTC'))];}private static function seal(array$scope,string$id,array$data):string{return Crypto::encrypt(json_encode(['owner'=>[...$scope,$id],'draft'=>$data],JSON_THROW_ON_ERROR));}private static function assertEditable(array$row,int$revision):void{if((int)$row['revision']!==$revision)self::conflict();if($row['sending'])throw new ApiError(409,'MPEI_MAIL_DELIVERY_UNKNOWN','Сначала проверьте, было ли отправлено это письмо.');}private static function conflict():never{throw new ApiError(409,'MPEI_MAIL_DRAFT_CHANGED','Черновик изменился. Откройте его заново.');}private static function storageError():ApiError{return new ApiError(503,'MPEI_MAIL_TEMPORARY_STORAGE','Не удалось подготовить вложение черновика.');}}